def min_cover(inp,out,seed):
    S=[(i,j) for i,r in enumerate(inp) for j,v in enumerate(r) if v==seed]
    H,W=len(inp),len(inp[0])
    mn=(min(i for i,_ in S),min(j for _,j in S))
    rel=[(i-mn[0],j-mn[1]) for i,j in S]
    D=set(diff_cells(inp,out,seed))
    cands=[]
    for i in range(H):
        for j in range(W):
            cells={(i+di,j+dj) for di,dj in rel}
            if all(0<=ci<H and 0<=cj<W for ci,cj in cells):
                cover=cells&D
                if cover: cands.append((i-mn[0],j-mn[1],cover))
    # greedy set cover
    uncov=set(D); chosen=[]
    while uncov:
        best=max(cands,key=lambda c:len(c[2]&uncov))
        chosen.append((best[0],best[1])); uncov-=best[2]
    return sorted(set(chosen)), len(D)
