def largest_comp_color(grid):
    H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]
    best=None;bn=-1
    from collections import deque
    for i in range(H):
        for j in range(W):
            if seen[i][j]: continue
            v=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True; n=0
            while q:
                x,y=q.popleft(); n+=1
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    a_,b_=x+dx,y+dy
                    if 0<=a_<H and 0<=b_<W and not seen[a_][b_] and grid[a_][b_]==v:
                        seen[a_][b_]=True;q.append((a_,b_))
            if n>bn: bn,best=n,v
    return best
